// Draw an 88x88 weather icon at (x,y).
template<typename TDisplay>
void drawWeatherIcon(TDisplay& display, const uint8_t* bmp, int16_t x, int16_t y) {
  static const uint16_t COLORS[] = {
    GxEPD_WHITE, GxEPD_BLACK, GxEPD_RED, GxEPD_YELLOW, GxEPD_GREEN, GxEPD_BLUE
  };
  int idx=0;
  for(int16_t row=0;row<88;row++){
    for(int16_t col=0;col<88;col+=2){
      uint8_t b=pgm_read_byte(&bmp[idx++]);
      uint8_t hi=(b>>4)&0xF, lo=b&0xF;
      if(hi<6) display.drawPixel(x+col,  y+row,COLORS[hi]);
      if(lo<6) display.drawPixel(x+col+1,y+row,COLORS[lo]);
    }
  }
}

// Pick 88x88 weather icon for a pretty condition string.
inline const uint8_t* weatherIconBitmap(const String& condition) {
  if (condition == "Sunny")              return icon_sunny;
  if (condition == "Clear Night")        return icon_night;
  if (condition == "Partly Cloudy")      return icon_partly_cloudy;
  if (condition == "Partly Cloudy Night")return icon_night_partly_cloudy;
  if (condition == "Cloudy")             return icon_cloudy;
  if (condition == "Rainy")              return icon_rainy;
  if (condition == "Pouring")            return icon_pouring;
  if (condition == "Thunderstorms")      return icon_lightning_rainy;
  if (condition == "Snowy")              return icon_snowy;
  if (condition == "Sleet")              return icon_snowy_rainy;
  if (condition == "Fog")                return icon_fog;
  if (condition == "Windy")              return icon_windy;
  if (condition == "Hail")               return icon_snowy;
  if (condition == "Lightning")          return icon_lightning_rainy;
  if (condition == "Exceptional")        return icon_cloudy;
  return icon_cloudy;
}